CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '' CHECK (char_length(name) <= 100), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_own_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_own_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('admin', 'seller');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'seller', UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name) VALUES (NEW.id,left(coalesce(NEW.raw_user_meta_data->>'name',''),100)); INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'seller'); RETURN NEW; END $$;
CREATE TRIGGER create_app_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
INSERT INTO public.profiles(id,name) SELECT id,left(coalesce(raw_user_meta_data->>'name',''),100) FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'seller'::public.app_role FROM auth.users ON CONFLICT DO NOTHING;
ALTER POLICY "acesso erp produtos" ON public.produtos TO authenticated USING (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin'));
ALTER POLICY "acesso erp ordens" ON public.ordens_compra TO authenticated USING (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin'));
ALTER POLICY "acesso erp notificacoes" ON public.notificacoes TO authenticated USING (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin'));
ALTER POLICY "acesso erp config" ON public.configuracoes_erp TO authenticated USING (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin'));
REVOKE ALL ON public.produtos,public.ordens_compra,public.notificacoes,public.configuracoes_erp FROM anon;
ALTER TABLE public.produtos ADD COLUMN preco_venda numeric(12,2) NOT NULL DEFAULT 0 CHECK (preco_venda >= 0);
UPDATE public.produtos SET preco_venda = custo_unitario;
CREATE TABLE public.customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100), document text CHECK (char_length(document) <= 18), phone text CHECK (char_length(phone) <= 25), email text CHECK (char_length(email) <= 255), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.customers TO authenticated;
GRANT ALL ON public.customers TO service_role;
ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE POLICY customer_staff ON public.customers FOR ALL TO authenticated USING (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, customer_id uuid REFERENCES public.customers(id), total_amount numeric(12,2) NOT NULL DEFAULT 0 CHECK(total_amount >= 0), payment_method text NOT NULL CHECK(payment_method IN ('cash','credit','debit','pix')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('completed','pending','canceled')), request_id uuid NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.sales TO authenticated;
GRANT ALL ON public.sales TO service_role;
ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
CREATE POLICY sale_staff_read ON public.sales FOR SELECT TO authenticated USING (user_id = auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.sale_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES public.sales(id), product_id text NOT NULL REFERENCES public.produtos(id), quantity integer NOT NULL CHECK(quantity > 0 AND quantity <= 100000), unit_price numeric(12,2) NOT NULL CHECK(unit_price > 0), subtotal numeric(12,2) GENERATED ALWAYS AS (quantity * unit_price) STORED, UNIQUE(sale_id,product_id));
GRANT SELECT ON public.sale_items TO authenticated;
GRANT ALL ON public.sale_items TO service_role;
ALTER TABLE public.sale_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY items_sale_read ON public.sale_items FOR SELECT TO authenticated USING (EXISTS(SELECT 1 FROM public.sales WHERE sales.id = sale_id));
CREATE FUNCTION public.complete_sale_stock() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE item record; BEGIN IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed' THEN IF OLD.status <> 'pending' THEN RAISE EXCEPTION 'Venda não pode ser finalizada'; END IF; IF NOT EXISTS(SELECT 1 FROM public.sale_items WHERE sale_id = NEW.id) THEN RAISE EXCEPTION 'Carrinho vazio'; END IF; FOR item IN SELECT * FROM public.sale_items WHERE sale_id = NEW.id ORDER BY product_id LOOP PERFORM 1 FROM public.produtos WHERE id = item.product_id FOR UPDATE; UPDATE public.produtos SET estoque = estoque - item.quantity, updated_at = now() WHERE id = item.product_id AND estoque - reservado >= item.quantity; IF NOT FOUND THEN RAISE EXCEPTION 'Estoque Insuficiente'; END IF; END LOOP; SELECT sum(subtotal) INTO NEW.total_amount FROM public.sale_items WHERE sale_id = NEW.id; ELSIF OLD.status = 'completed' AND NEW.status <> OLD.status THEN RAISE EXCEPTION 'Venda finalizada não pode ser alterada'; END IF; RETURN NEW; END $$;
CREATE TRIGGER sale_stock BEFORE UPDATE ON public.sales FOR EACH ROW EXECUTE FUNCTION public.complete_sale_stock();
CREATE FUNCTION public.checkout_sale(p_items jsonb, p_payment text, p_request_id uuid, p_customer_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE sale_id uuid; item record; product record; BEGIN IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'seller') OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Acesso negado'; END IF; IF p_payment NOT IN ('cash','credit','debit','pix') OR p_payment IS NULL THEN RAISE EXCEPTION 'Pagamento inválido'; END IF; IF jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Carrinho inválido'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text,0)); SELECT id INTO sale_id FROM public.sales WHERE request_id = p_request_id AND user_id = auth.uid(); IF FOUND THEN RETURN sale_id; END IF; IF p_customer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN RAISE EXCEPTION 'Cliente inválido'; END IF; INSERT INTO public.sales(user_id,customer_id,payment_method,request_id) VALUES(auth.uid(),p_customer_id,p_payment,p_request_id) RETURNING id INTO sale_id; FOR item IN SELECT product_id,sum(quantity)::integer AS quantity FROM jsonb_to_recordset(p_items) AS x(product_id text,quantity integer) GROUP BY product_id ORDER BY product_id LOOP IF item.quantity IS NULL OR item.quantity < 1 OR item.quantity > 100000 THEN RAISE EXCEPTION 'Quantidade inválida'; END IF; SELECT * INTO product FROM public.produtos WHERE id = item.product_id FOR UPDATE; IF NOT FOUND OR product.preco_venda <= 0 THEN RAISE EXCEPTION 'Produto sem preço de venda'; END IF; IF product.estoque - product.reservado < item.quantity THEN RAISE EXCEPTION 'Estoque Insuficiente'; END IF; INSERT INTO public.sale_items(sale_id,product_id,quantity,unit_price) VALUES(sale_id,item.product_id,item.quantity,product.preco_venda); END LOOP; UPDATE public.sales SET status = 'completed' WHERE id = sale_id; RETURN sale_id; END $$;
REVOKE ALL ON FUNCTION public.checkout_sale(jsonb,text,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.checkout_sale(jsonb,text,uuid,uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.create_user_profile(),public.complete_sale_stock() FROM PUBLIC;